create or replace function public.icash_daily_claim(p_account uuid) returns void language plpgsql set search_path='' as $$ declare last_budget bigint;begin update public.icash_daily_plans p set account_id=p_account where p.account_id is null and exists(select 1 from public.icash_funding_orders o where o.daily_plan_id=p.id and o.account_id=p_account);select credit_cents into last_budget from public.icash_funding_orders where account_id=p_account and daily_plan_id is not null and mode='live' and state='paid' order by paid_at desc,created_at desc limit 1;if last_budget is not null then update public.icash_accounts set daily_limit_cents=last_budget where id=p_account;end if;end $$;
